"""Reviewed offline workbook generator/reference. Executed only in the recipe container."""
import base64
import io
import json
import random
import sys
import zipfile
from datetime import datetime

from openpyxl import Workbook, load_workbook
from openpyxl.styles import Font

HEADERS = ['ID', 'Date', 'Quantity', 'Price', 'Amount']
TASK = ('Clean Data rows: preserve first occurrence of each ID; discard rows with invalid numeric '
        'quantity/price; missing numbers become zero. Preserve order and ID text. Normalize dates '
        'to YYYY-MM-DD text. Set Amount to a relative Quantity*Price formula on every retained row. '
        'Write Summary!A1="Total" and Summary!B1=SUM(Data!E2:E<last-row>). Preserve other sheets '
        'and their values. Keep all Data header cells bold. Save an XLSX with recalculated formula '
        'caches; return its base64 bytes as workbook_b64. No macros or external links.')
VARIATIONS = ['mixed_types_dates', 'missing_invalid', 'duplicates', 'multiple_sheets',
              'formulas', 'structure_formatting', 'unicode_sparse']


def encode(book):
    book.properties.created = book.properties.modified = datetime(2000, 1, 1)
    stream = io.BytesIO()
    book.save(stream)
    return canonical(stream.getvalue())


def canonical(raw):
    target = io.BytesIO()
    with zipfile.ZipFile(io.BytesIO(raw)) as source, zipfile.ZipFile(target, 'w') as dest:
        for name in sorted(source.namelist()):
            value = source.read(name)
            if name == 'docProps/core.xml':
                from xml.etree import ElementTree as ET
                root = ET.fromstring(value)
                for field in ('created', 'modified'):
                    root.find('{http://purl.org/dc/terms/}' + field).text = '2000-01-01T00:00:00Z'
                value = ET.tostring(root)
            info = zipfile.ZipInfo(name, (2000, 1, 1, 0, 0, 0))
            info.compress_type = zipfile.ZIP_DEFLATED
            dest.writestr(info, value)
    return base64.b64encode(target.getvalue()).decode()


def render(rows, extras):
    book = Workbook()
    sheet = book.active
    sheet.title = 'Data'
    sheet.append(HEADERS)
    for row in rows:
        sheet.append(row)
    for cell in sheet[1]:
        cell.font = Font(bold=True)
    for name, value in extras.items():
        book.create_sheet(name)['A1'] = value
    return encode(book)


def clean(rows):
    result, seen = [], set()
    for identity, date, quantity, price, *_ in rows:
        if identity is None or identity in seen:
            continue
        seen.add(identity)
        try:
            quantity = int(quantity or 0)
            price = int(price or 0)
            date = datetime.strptime(str(date)[:10], '%Y-%m-%d').strftime('%Y-%m-%d')
        except (TypeError, ValueError):
            continue
        result.append([str(identity), date, quantity, price, quantity * price])
    return result


def generate(payload):
    rng = random.Random(payload['seed'])
    cases = []
    for stage in payload['stages']:
        for index in range(stage['count']):
            variation = VARIATIONS[index % len(VARIATIONS)]
            rows = [[f'{stage["split"]}-{rng.getrandbits(48):012x}-{i}', f'2026-09-{i+1:02}',
                     rng.randrange(1, 20), rng.randrange(1, 100), None] for i in range(2 + index % 14)]
            extras = {'Notes': 'Preserve this note'} if variation in {'multiple_sheets', 'structure_formatting'} else {}
            if variation == 'mixed_types_dates':
                for row in rows[::2]:
                    row[2] = str(row[2])
                    row[1] = datetime.strptime(row[1], '%Y-%m-%d')
            elif variation == 'missing_invalid':
                rows[0][2] = None
                rows[-1][3] = 'invalid'
            elif variation == 'duplicates':
                rows.insert(1, list(rows[0]))
                rows[1][3] = 999
            elif variation == 'formulas':
                for row in rows:
                    row[4] = '=1+1'
            elif variation == 'unicode_sparse':
                rows[0][0] = '東京\u2013Zoë-' + rows[0][0]
                rows.insert(1, [None] * 5)
            truth = {'rows': clean(rows), 'extras': extras}
            value = {'workbook_b64': render(rows, extras), 'task': TASK,
                     'variation': variation, 'row_bound': len(rows)}
            cases.append({'input': value, 'output': truth, 'variation': variation,
                          'template_family': 'workbook:' + variation})
    return {'cases': cases}


def reference(value):
    # Read the actual rendered input; generator truth is never an input here.
    book = load_workbook(io.BytesIO(base64.b64decode(value['workbook_b64'])), data_only=False)
    rows = clean(list(book['Data'].values)[1:])
    sheet = book['Data']
    sheet.delete_rows(2, sheet.max_row)
    for index, row in enumerate(rows, 2):
        sheet.append([*row[:4], f'=C{index}*D{index}'])
    if 'Summary' not in book:
        book.create_sheet('Summary')
    book['Summary']['A1'] = 'Total'
    book['Summary']['B1'] = f'=SUM(Data!E2:E{len(rows)+1})'
    # openpyxl writes formulas without caches. Populate this deterministic
    # reference's caches; the separate grader recomputes from actual cells.
    from xml.etree import ElementTree as ET
    raw = base64.b64decode(encode(book))
    target = io.BytesIO()
    ns = '{http://schemas.openxmlformats.org/spreadsheetml/2006/main}'
    with zipfile.ZipFile(io.BytesIO(raw)) as source, zipfile.ZipFile(target, 'w', zipfile.ZIP_DEFLATED) as dest:
        for name in source.namelist():
            data = source.read(name)
            if name.startswith('xl/worksheets/'):
                root = ET.fromstring(data)
                for cell in root.iter(ns+'c'):
                    formula = cell.find(ns+'f')
                    if formula is None:
                        continue
                    cached = cell.find(ns+'v')
                    if cached is None:
                        cached = ET.SubElement(cell, ns+'v')
                    cached.text = str(sum(row[4] for row in rows) if formula.text.startswith('SUM(')
                                      else rows[int(cell.attrib['r'][1:])-2][4])
                data = ET.tostring(root)
            dest.writestr(name, data)
    return {'workbook_b64': canonical(target.getvalue())}


if __name__ == '__main__':
    payload = json.load(sys.stdin)
    print(json.dumps(generate(payload) if sys.argv[1] == 'generate'
                     else {'outputs': [reference(value) for value in payload['inputs']]}))

"""Independent bounded OOXML grader; supports only the recipe's product/SUM formulas."""
import base64
import io
import json
import posixpath
import sys
import zipfile
from decimal import Decimal
from xml.etree import ElementTree as ET

N = '{http://schemas.openxmlformats.org/spreadsheetml/2006/main}'
R = '{http://schemas.openxmlformats.org/officeDocument/2006/relationships}'


def inspect(encoded):
    if not isinstance(encoded, str) or len(encoded) > 200000:
        raise ValueError('oversized workbook')
    with zipfile.ZipFile(io.BytesIO(base64.b64decode(encoded, validate=True))) as archive:
        entries = archive.infolist()
        if (len(entries) > 100 or len({item.filename for item in entries}) != len(entries)
                or sum(item.file_size for item in entries) > 2000000
                or any('..' in item.filename.split('/') or item.filename.startswith('/')
                       or 'vba' in item.filename.lower() or 'externallink' in item.filename.lower() for item in entries)):
            raise ValueError('unsupported workbook archive')
        def xml(name):
            value = archive.read(name)
            if b'<!DOCTYPE' in value or b'<!ENTITY' in value:
                raise ValueError('XML declarations denied')
            return ET.fromstring(value)
        links = xml('xl/_rels/workbook.xml.rels')
        if any(item.get('TargetMode') == 'External' for item in links):
            raise ValueError('external relationships denied')
        targets = {item.get('Id'): posixpath.normpath(posixpath.join('xl', item.get('Target', '').lstrip('/')))
                   if not item.get('Target', '').startswith('/') else item.get('Target').lstrip('/') for item in links}
        strings = []
        if 'xl/sharedStrings.xml' in archive.namelist():
            strings = [''.join(item.itertext()) for item in xml('xl/sharedStrings.xml').findall(N+'si')]
        sheets = {}
        for sheet in xml('xl/workbook.xml').find(N+'sheets'):
            cells = {}
            for cell in xml(targets[sheet.get(R+'id')]).iter(N+'c'):
                address = cell.get('r')
                if address in cells:
                    raise ValueError('duplicate cell')
                value, formula = cell.findtext(N+'v'), cell.findtext(N+'f')
                if cell.get('t') == 'inlineStr':
                    value = ''.join(cell.find(N+'is').itertext())
                elif cell.get('t') == 's':
                    value = strings[int(value)]
                elif cell.get('t') == 'str':
                    pass  # OOXML string values are text, including numeric-looking IDs.
                elif cell.get('t') not in (None, 'n'):
                    raise ValueError('unsupported cell type')
                elif value is not None:
                    value = Decimal(value)
                cells[address] = (value, formula, int(cell.get('s', '0')))
            if sheet.get('name') in sheets:
                raise ValueError('duplicate sheet')
            sheets[sheet.get('name')] = cells
        styles = xml('xl/styles.xml')
        fonts = list(styles.find(N+'fonts'))
        bold = {index for index, style in enumerate(styles.find(N+'cellXfs'))
                if fonts[int(style.get('fontId', '0'))].find(N+'b') is not None
                and fonts[int(style.get('fontId', '0'))].find(N+'b').get('val', '1') not in {'0', 'false'}}
        return sheets, bold


def failure_code(example):
    try:
        if not isinstance(example['output'], dict) or set(example['output']) != {'workbook_b64'}:
            return 'output_contract'
        sheets, bold = inspect(example['output']['workbook_b64'])
        truth = example['expected']
        if set(sheets) != {'Data', 'Summary', *truth['extras']}:
            return 'sheet_set'
        data = sheets['Data']
        expected_addresses = {f'{col}{row}' for row in range(1, len(truth['rows'])+2) for col in 'ABCDE'}
        if {key for key, item in data.items() if item[0] is not None or item[1] is not None} != expected_addresses:
            return 'data_extent'
        for col, header in zip('ABCDE', ['ID', 'Date', 'Quantity', 'Price', 'Amount'], strict=True):
            if data[col+'1'][0] != header or data[col+'1'][2] not in bold:
                return 'header_format'
        recomputed = Decimal(0)
        for index, expected in enumerate(truth['rows'], 2):
            for col, value in zip('ABCDE', expected, strict=True):
                if data[f'{col}{index}'][0] != value:
                    return 'formula_cache' if col == 'E' else 'cell_value'
            # No eval: the reviewed formula grammar is exactly these references.
            if data[f'E{index}'][1] != f'C{index}*D{index}':
                return 'row_formula'
            product = data[f'C{index}'][0] * data[f'D{index}'][0]
            if data[f'E{index}'][0] != product:
                return 'formula_cache'
            recomputed += product
        summary = sheets['Summary']
        if (summary['A1'][0] != 'Total' or summary['B1'][0] != recomputed
                or summary['B1'][1] != f'SUM(Data!E2:E{len(truth["rows"])+1})'):
            return 'summary'
        return None if all({key: cell[:2] for key, cell in sheets[name].items()} == {'A1': (value, None)} for name, value in truth['extras'].items()) else 'preserved_sheets'
    except (ValueError, TypeError, KeyError, IndexError, AttributeError, ArithmeticError, RuntimeError, NotImplementedError, ET.ParseError, zipfile.BadZipFile):
        return 'invalid_workbook'


def grade(example):
    return failure_code(example) is None


if __name__ == '__main__':
    payload = json.load(sys.stdin)
    codes = [failure_code(example) for example in payload['examples']]
    result = {'valid': [code is None for code in codes]}
    if sys.argv[1:] == ['diagnose']:
        result['failure_codes'] = codes
    print(json.dumps(result))

